'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(Number(v)||0);
const icon=(key,cls='')=>`<svg class="icon ${cls}" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[key]||ICONS.box}</svg>`;
const image=(key,alt,cls='')=>`<img class="${cls}" src="${/^data:image\/(png|jpeg|webp);base64,/.test(key)?key:ASSETS[key]||ASSETS['product-silver']}" alt="${esc(alt)}" decoding="async">`;
const button=(label,action,cls='',data='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${data}>${label}</button>`;
const link=(label,route,cls='')=>`<a class="${cls}" href="#${route}">${label}</a>`;
const badge=(label,tone='neutral')=>`<span class="badge ${tone}"><span class="dot"></span>${esc(label)}</span>`;
const labels={PENDING:'Chờ xác nhận',CONFIRMED:'Đã xác nhận',PROCESSING:'Đang chuẩn bị',SHIPPING:'Đang giao',DELIVERED:'Đã giao',CANCELLED:'Đã hủy',RETURNED:'Đã trả hàng',PAID:'Đã thanh toán',FAILED:'Thất bại',DRAFT:'Nháp',PARTIALLY_RECEIVED:'Nhận một phần',RECEIVED:'Đã nhận đủ'};
const statusBadge=s=>badge(labels[s]||s,({PENDING:'orange',CONFIRMED:'blue',PROCESSING:'blue',SHIPPING:'blue',DELIVERED:'green',PAID:'green',RECEIVED:'green',CANCELLED:'red',FAILED:'red',PARTIALLY_RECEIVED:'orange'})[s]||'neutral');
const paymentBadge=s=>badge(({PENDING:'Chưa thanh toán',PAID:'Đã thanh toán',FAILED:'Thất bại',CANCELLED:'Đã hủy'})[s]||s,({PENDING:'orange',PAID:'green',FAILED:'red'})[s]||'neutral');
const option=(value,label,selected)=>`<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`;
const field=(label,name,value='',type='text',attrs='')=>`<label class="field"><span>${label}</span><input type="${type}" name="${name}" value="${esc(value)}" ${attrs}></label>`;
const selectField=(label,name,values,selected)=>`<label class="field"><span>${label}</span><select name="${name}">${values.map(v=>option(Array.isArray(v)?v[0]:v,Array.isArray(v)?v[1]:v,selected)).join('')}</select></label>`;
const textarea=(label,name,value='',attrs='')=>`<label class="field"><span>${label}</span><textarea name="${name}" ${attrs}>${esc(value)}</textarea></label>`;
const table=(headers,rows)=>`<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}" class="table-empty">Không có dữ liệu phù hợp. Thử thay đổi bộ lọc.</td></tr>`}</tbody></table></div>`;
const primaryCell=(a,b='')=>`<div class="primary-cell">${esc(a)}</div>${b?`<div class="subcell">${esc(b)}</div>`:''}`;
const metric=(title,value,sub,ic='chart')=>`<div class="metric"><div class="metric-label">${title}${icon(ic)}</div><div class="metric-value">${value}</div><small>${sub}</small></div>`;
const heading=(eyebrow,title,sub='',actions='')=>`<div class="page-heading"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${actions?`<div class="row wrap no-print">${actions}</div>`:''}</div>`;
const empty=(title,copy,action='Khám phá laptop',route='catalog',ic='box')=>`<div class="empty"><div class="empty-icon">${icon(ic)}</div><h2>${title}</h2><p>${copy}</p>${link(action,route,'btn primary')}</div>`;
