const findSku=sku=>{for(const p of state.products){const v=p.variants.find(v=>v.sku===sku);if(v)return {p,v};}return null;};
const orderTotal=o=>o.items.reduce((s,i)=>s+i.qty*i.price,0)-(o.discount||0);
const currentOrder=()=>state.orders.find(o=>o.id===ui.order)||state.orders[0];
const addressText=a=>[a.street,a.ward,a.district,a.city].filter(Boolean).join(', ');
function cartData(){return state.cart.map(i=>({...i,...findSku(i.sku)})).filter(i=>i.p&&i.v);}
function couponDiscount(subtotal,code=state.coupon){const c=state.coupons.find(c=>c.code===String(code).trim().toUpperCase()&&c.active);if(!c||subtotal<c.min)return 0;const date=new Date().toISOString().slice(0,10);if(date<c.start||date>c.end)return 0;const used=state.orders.filter(o=>o.coupon===c.code&&o.status!=='CANCELLED');if(used.length>=c.limit||used.filter(o=>o.customerId==='u1').length>=c.perUser)return 0;const d=c.type==='FIXED'?c.value:subtotal*c.value/100;return Math.min(subtotal,c.max>0?Math.min(c.max,d):d);}
function totals(){const subtotal=cartData().reduce((s,i)=>s+i.qty*i.v.price,0);const discount=couponDiscount(subtotal);return {subtotal,discount,total:subtotal-discount};}
function toast(message,error=false){$('#toast')?.remove();const n=document.createElement('div');n.id='toast';n.className='toast'+(error?' error':'');n.setAttribute('role',error?'alert':'status');n.innerHTML=icon(error?'alert':'check')+`<span>${esc(message)}</span>`;document.body.appendChild(n);clearTimeout(toast.timer);toast.timer=setTimeout(()=>n.remove(),4200);}
function modal(title,body,actions='',wide=false){const d=$('#modal');d.className='modal'+(wide?' wide':'');d.innerHTML=`<div class="modal-head"><h2>${title}</h2><button type="button" class="icon-btn" data-action="close-modal" aria-label="Đóng hộp thoại">${icon('close')}</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}`;d.showModal();}
function confirmAction(title,copy,action,label='Xác nhận',data=''){modal(title,`<p class="muted">${esc(copy)}</p>`,button('Hủy','close-modal')+button(label,action,'primary',data));}
function closeModal(){const d=$('#modal');if(d.open)d.close();}
