function demoBar(){return `<div class="demo-bar no-print"><div class="row"><span class="demo-note">BẢN TRẢI NGHIỆM · DỮ LIỆU MẪU</span><button data-action="screen-map">${icon('grid')}<span>Bản đồ giao diện</span></button></div><div class="role-switch"><label for="role-switch">Vai trò</label><select id="role-switch" aria-label="Chọn vai trò trải nghiệm"><option value="user" ${ui.role==='user'?'selected':''}>Khách hàng</option><option value="staff" ${ui.role==='staff'?'selected':''}>Staff</option><option value="admin" ${ui.role==='admin'?'selected':''}>Admin</option></select><button data-action="reset-demo" title="Khôi phục dữ liệu mẫu">${icon('refresh')}</button></div></div>`;}
