function productCard(p){const v=p.variants[0];return `<article class="product-card"><a href="#detail&product=${p.id}" class="product-visual" aria-label="Xem ${esc(p.name)}"><span class="mini-tag">${p.category.toUpperCase()}</span>${image(p.customImage||p.asset,p.name)}</a><div class="eyebrow" style="font-size:9px;letter-spacing:1px;margin:0">${p.brand}</div><h3>${link(esc(p.name),'detail&product='+p.id)}</h3><p class="spec">${esc(p.cpu)} · ${esc(v.ram)} · ${esc(v.storage)}</p><div class="price">${money(v.price)}</div><div class="card-foot"><span class="rating"><span class="star">★</span> 4.9 <span class="muted">· Chính hãng</span></span>${link(`${icon('arrow-right')}<span class="sr-only">Xem ${esc(p.name)}</span>`,'detail&product='+p.id,'btn sm')}</div></article>`;}
function home(){return `${shopHeader()}<main id="main"><div class="container"><section class="hero"><div class="hero-copy"><div class="eyebrow">MỞ MÁY LÊN. MỞ ĐIỀU MỚI.</div><h1>Chiếc laptop cho <span class="hero-line">mọi <em>ý tưởng.</em></span></h1><p>Học điều mới, tạo điều hay, chinh phục thử thách.<br>Tìm người bạn đồng hành đúng chất bạn.</p><div class="row">${link('Khám phá laptop '+icon('arrow-right'),'catalog','btn primary')}${link('Tư vấn cùng AI','ai','btn')}</div></div><div class="hero-art">${image('hero-laptop','Minh họa laptop bạc với hình nền cam nguyên bản')}<div class="hero-label">${icon('shield')}<div><strong>Chính hãng. An tâm.</strong><br><span class="muted">Chọn chiếc máy, trao niềm tin.</span></div></div></div></section><div class="trust-row">${[['shield','Chính hãng 100%','Yên tâm chọn lựa'],['truck','Giao hàng toàn quốc','Nhanh chóng, tận nơi'],['wallet','Thanh toán linh hoạt','COD hoặc VNPay'],['headset','Tư vấn tận tâm','Tìm đúng chiếc máy']].map(([ic,a,b])=>`<div class="trust-item">${icon(ic)}<div><strong>${a}</strong><small>${b}</small></div></div>`).join('')}</div><section class="section"><div class="section-head"><div><div class="eyebrow">LỰA CHỌN DÀNH CHO BẠN</div><h2>Đúng nhu cầu. Đúng chiếc máy.</h2><p class="muted">Những cấu hình được yêu thích, sẵn sàng cho ngày mới.</p></div>${link('Xem tất cả '+icon('arrow-right'),'catalog','btn sm')}</div><div class="chips">${['Tất cả laptop','Gaming','Văn phòng','Mỏng nhẹ'].map((c,i)=>`<button class="chip ${ui.homeCategory===c||!ui.homeCategory&&!i?'active':''}" data-action="home-category" data-category="${c}">${c}</button>`).join('')}</div><div class="products-grid">${state.products.filter(p=>p.active&&(!ui.homeCategory||ui.homeCategory==='Tất cả laptop'||p.category===ui.homeCategory)).slice(0,4).map(productCard).join('')}</div></section><section class="section" style="padding-top:8px"><div class="collection-grid"><div class="collection orange"><div><div class="eyebrow" style="font-size:9px">WORK ANYWHERE</div><h3>Nhẹ hành trang.<br>Rộng cảm hứng.</h3><p>Không gian làm việc theo bạn đến mọi nơi.</p>${link('Laptop mỏng nhẹ '+icon('arrow-right'),'catalog&category=Mỏng nhẹ','text-btn')}</div>${image('product-silver','Laptop mỏng nhẹ màu bạc')}</div><div class="collection"><div><div class="eyebrow" style="font-size:9px">PLAY YOUR WAY</div><h3>Sẵn sàng cho<br>trận đấu lớn.</h3><p>Cấu hình mạnh. Từng khung hình mượt mà.</p>${link('Khám phá gaming '+icon('arrow-right'),'catalog&category=Gaming','text-btn')}</div>${image('product-dark','Laptop gaming màu đen')}</div></div></section><div class="ai-banner"><div class="ai-symbol">${icon('sparkles')}</div><div><h3>Chưa biết chọn máy nào?</h3><p class="muted">Kể cho AI nghe nhu cầu và ngân sách của bạn.</p></div>${link('Tìm máy cùng AI '+icon('arrow-right'),'ai','btn primary push')}</div></div></main>${footer()}`;}
function filteredProducts(){return state.products.filter(p=>p.active&&(!ui.search||(p.name+' '+p.brand+' '+p.variants.map(v=>v.sku).join(' ')).toLowerCase().includes(ui.search.toLowerCase()))&&(!ui.filterBrand||p.brand===ui.filterBrand)&&(!ui.filterCategory||p.category===ui.filterCategory)&&(!ui.filterRam||p.variants.some(v=>v.ram===ui.filterRam))&&(!ui.maxPrice||p.variants[0].price<=Number(ui.maxPrice))).sort((a,b)=>ui.sort==='low'?a.variants[0].price-b.variants[0].price:ui.sort==='high'?b.variants[0].price-a.variants[0].price:0);}
function catalog(){const products=route==='emptySearch'?[]:filteredProducts();return `${shopHeader()}<main id="main" class="container section"><div class="breadcrumb">${link('Trang chủ','home')}<span>/</span><span>Tất cả laptop</span></div>${heading('KHÁM PHÁ CÔNG NGHỆ','Tìm chiếc laptop dành cho bạn.','Một lựa chọn phù hợp, hàng ngàn điều có thể.')}<div class="catalog-layout"><aside class="filters ${ui.filtersOpen?'open':''}" id="catalog-filters"><div class="row between"><h3>Bộ lọc tìm kiếm</h3><button class="text-btn small" data-action="clear-filters">Xóa tất cả</button></div>${[['Thương hiệu','filterBrand',state.brands.filter(b=>b.active).map(b=>b.name)],['Nhu cầu sử dụng','filterCategory',state.categories.filter(c=>c.active).map(c=>c.name)],['RAM','filterRam',['16GB','32GB']]].map(([title,key,vals])=>`<div class="filter-group"><h4>${title}</h4>${vals.map(v=>`<label class="check-label"><input type="checkbox" data-filter="${key}" value="${v}" ${ui[key]===v?'checked':''}>${v}</label>`).join('')}</div>`).join('')}<div class="filter-group"><h4>Khoảng giá</h4><select data-filter="maxPrice" aria-label="Giá tối đa">${[['','Tất cả mức giá'],[20000000,'Dưới 20 triệu'],[25000000,'Đến 25 triệu'],[30000000,'Đến 30 triệu']].map(([v,l])=>option(v,l,ui.maxPrice)).join('')}</select></div></aside><div><div class="toolbar"><span class="results-count"><strong>${products.length}</strong> laptop phù hợp</span><button class="btn sm mobile-only" data-action="toggle-filters">${icon('filter')}Bộ lọc</button><select data-filter="sort" aria-label="Sắp xếp sản phẩm">${[['featured','Được đề xuất'],['low','Giá: thấp đến cao'],['high','Giá: cao đến thấp']].map(([v,l])=>option(v,l,ui.sort)).join('')}</select><form class="search" data-form="search">${icon('search')}<input name="q" aria-label="Tìm trong danh sách laptop" placeholder="Tìm tên laptop hoặc SKU..." value="${esc(ui.search)}"><button class="text-btn" aria-label="Tìm kiếm">${icon('arrow-right')}</button></form></div>${ui.filterBrand||ui.filterCategory||ui.filterRam||ui.search?`<div class="chips" style="margin-top:0">${[ui.filterBrand,ui.filterCategory,ui.filterRam,ui.search].filter(Boolean).map(v=>`<span class="badge orange">${esc(v)}</span>`).join('')}<button class="text-btn small" data-action="clear-filters">Xóa bộ lọc ×</button></div>`:''}${products.length?`<div class="products-grid catalog-products">${products.map(productCard).join('')}</div>`:empty('Chưa tìm thấy chiếc máy phù hợp','Thử thay đổi từ khóa hoặc bớt một vài bộ lọc. Chiếc laptop của bạn đang chờ được khám phá.','Xem tất cả laptop','catalog&clear=1','search')}</div></div></main>${footer()}`;}
function detail(){const p=state.products.find(p=>p.id===ui.selected)||state.products[0];const v=p.variants[ui.variant]||p.variants[0];const reviews=state.reviews.filter(r=>r.visible&&p.variants.some(v=>v.sku===r.sku));return `${shopHeader()}<main id="main" class="container section"><div class="breadcrumb">${link('Trang chủ','home')}<span>/</span>${link('Laptop','catalog')}<span>/</span><span>${esc(p.name)}</span></div><section class="product-detail"><div><div class="main-product-image">${image(ui.thumb===1?'product-silver':p.customImage||p.asset,p.name)}</div><div class="thumbs">${[p.asset,'product-silver',p.asset].map((a,i)=>`<button class="thumb ${ui.thumb===i?'active':''}" data-action="thumbnail" data-index="${i}" aria-label="Hình sản phẩm ${i+1}">${image(a,p.name)}</button>`).join('')}</div><div class="row wrap muted small" style="margin-top:22px;gap:24px"><span>${icon('shield')} Bảo hành chính hãng</span><span>${icon('truck')} Giao hàng miễn phí</span></div></div><div class="detail-info"><div class="eyebrow">${esc(p.brand)} / ${esc(p.category)}</div><h1>${esc(p.name)}</h1><span class="rating"><span class="star">★ ★ ★ ★ ★</span> 4.9 · ${Math.max(1,reviews.length)} đánh giá</span><p class="muted">${esc(p.description)}</p><strong class="small">Chọn cấu hình</strong><div class="variant-options">${p.variants.map((v,i)=>`<button class="variant-option ${ui.variant===i?'active':''}" data-action="variant" data-index="${i}"><strong>${esc(v.ram)} / ${esc(v.storage)}</strong><br><span class="small">${esc(v.color)}</span></button>`).join('')}</div><span class="small muted">SKU ${esc(v.sku)} · Màu ${esc(v.color)}</span><div class="detail-price">${money(v.price)}</div>${badge(v.quantity>0?`Còn ${v.quantity} chiếc · Sẵn sàng giao`:'Tạm hết hàng',v.quantity>0?'green':'red')}<div class="detail-actions">${button('Mua ngay','buy','primary',`data-sku="${v.sku}" ${v.quantity<1?'disabled':''}`)}${button(icon('cart')+' Thêm vào giỏ','add-cart','',`data-sku="${v.sku}" ${v.quantity<1?'disabled':''}`)}</div><div class="notice">${icon('tag')}<div><strong>LAPTOP500 · Giảm 500.000₫</strong><p>Đơn từ 20 triệu. Áp dụng tại bước thanh toán theo điều kiện của mã.</p></div></div></div></section><section class="section"><div class="grid2"><div class="panel"><h3 class="panel-title">Hiểu rõ chiếc máy của bạn</h3><table class="spec-table"><tbody>${[['Vi xử lý',p.cpu],['Đồ họa',p.gpu],['Màn hình',p.screen],['Bộ nhớ',v.ram+' · '+v.storage],['Pin',p.battery],['Trọng lượng',p.weight],['Hệ điều hành',p.os]].map(([a,b])=>`<tr><td>${a}</td><td>${esc(b)}</td></tr>`).join('')}</tbody></table></div><div class="panel"><div class="row between"><h3>Trải nghiệm từ người dùng</h3><span class="rating-large">4.9</span></div>${reviews.length?reviews.map(r=>`<div class="review-item"><div class="row between"><strong class="small">${esc(r.name)}</strong><span class="small muted">${r.date}</span></div><div style="color:#b86710">${'★'.repeat(r.rating)}</div><p>${esc(r.comment)}</p>${badge('Đã mua hàng','green')}</div>`).join(''):`<div class="review-item"><p class="muted">Chưa có đánh giá công khai cho cấu hình này. Cảm nhận của bạn sẽ giúp người mua tiếp theo lựa chọn dễ dàng hơn.</p></div>`}${link('Xem đơn hàng để đánh giá','orders','text-btn small')}</div></div></section></main>${footer()}`;}
function orderSummary(action=true,fromOrder){const t=fromOrder?{subtotal:fromOrder.items.reduce((s,i)=>s+i.qty*i.price,0),discount:fromOrder.discount||0,total:orderTotal(fromOrder)}:totals();return `<aside class="panel order-summary"><h3>Tóm tắt đơn hàng</h3><div class="summary-line"><span class="muted">Tạm tính</span><strong>${money(t.subtotal)}</strong></div><div class="summary-line"><span class="muted">Giảm giá</span><strong style="color:var(--green)">−${money(t.discount)}</strong></div><div class="summary-line"><span class="muted">Vận chuyển</span><strong>Miễn phí</strong></div><hr><div class="summary-line total"><span>Tổng cộng</span><strong data-testid="cart-total">${money(t.total)}</strong></div><p class="small muted" style="margin-bottom:20px">Đã bao gồm thuế VAT.</p>${action?link('Tiến hành thanh toán '+icon('arrow-right'),'checkout','btn primary full'):''}<div class="row small muted" style="margin-top:18px;font-size:10px">${icon('shield')}Thông tin của bạn luôn được bảo vệ</div></aside>`;}
function cart(){const items=route==='emptyCart'?[]:cartData();return `${shopHeader()}<main id="main" class="container section">${heading('MUA SẮM CỦA BẠN','Giỏ hàng','Một chiếc máy tuyệt vời đang chờ bạn.',link('Tiếp tục mua sắm','catalog','btn'))}${!items.length?empty('Giỏ hàng đang chờ điều mới','Khám phá những chiếc laptop phù hợp và thêm lựa chọn yêu thích vào giỏ.','Khám phá laptop','catalog','cart'):`<div class="content-columns"><div class="stack"><div class="panel">${items.map(i=>`<article class="cart-item">${image(i.p.customImage||i.p.asset,i.p.name)}<div><h3>${link(esc(i.p.name),'detail&product='+i.p.id)}</h3><p class="muted">${esc(i.v.ram)} · ${esc(i.v.storage)} · ${esc(i.v.color)}</p><p class="small muted" style="margin:6px 0 12px">SKU ${i.v.sku}</p><strong>${money(i.v.price)}</strong></div><div class="stack item-controls"><div class="quantity">${button('−','qty','',`data-sku="${i.sku}" data-delta="-1" aria-label="Giảm số lượng"`)}<span data-testid="quantity">${i.qty}</span>${button('+','qty','',`data-sku="${i.sku}" data-delta="1" aria-label="Tăng số lượng"`)}</div><button class="text-btn small muted" data-action="remove-cart" data-sku="${i.sku}">Xóa sản phẩm</button></div></article>`).join('')}</div><div class="panel"><h3 style="margin-bottom:16px">Thêm một chút ưu đãi</h3><form class="row" data-form="coupon"><label class="field" style="flex:1"><span class="sr-only">Mã giảm giá</span><input name="code" placeholder="Nhập mã giảm giá" value="${esc(state.coupon)}" required></label><button class="btn">Áp dụng</button></form><p class="small muted" style="margin-top:12px">Thử WELCOME5 để giảm 5%, tối đa 1.000.000₫.</p>${state.coupon?`<div class="row between" style="margin-top:12px">${badge(totals().discount?state.coupon+' · Đã áp dụng':'Mã chưa đủ điều kiện',totals().discount?'green':'orange')}<button class="text-btn small" data-action="remove-coupon">Gỡ mã</button></div>`:''}</div></div>${orderSummary()}</div>`}</main>${footer()}`;}
function checkout(){const items=cartData();const selected=(state.addresses.some(a=>a.id===ui.address)?ui.address:null)||state.addresses.find(a=>a.isDefault)?.id||state.addresses[0]?.id;return `${shopHeader()}<main id="main" class="container section">${heading('CHỈ CÒN MỘT BƯỚC NỮA','Hoàn tất đơn hàng','Thông tin rõ ràng. Mua sắm an tâm.',link('Quay lại giỏ hàng','cart','btn'))}${!items.length?empty('Giỏ hàng của bạn đang trống','Hãy thêm một sản phẩm để bắt đầu thanh toán.','Khám phá laptop','catalog','cart'):`<form data-form="checkout" class="content-columns"><div class="stack"><section class="panel"><div class="row between panel-title"><h3>01 / Địa chỉ nhận hàng</h3><button type="button" class="text-btn small" data-action="new-address-checkout">Thêm địa chỉ</button></div><div class="stack">${state.addresses.map(a=>`<label class="address-option"><input type="radio" name="address" value="${a.id}" required ${selected===a.id?'checked':''}><span><strong>${esc(a.name)} · ${esc(a.phone)}</strong><span class="small muted" style="display:block;margin:6px 0">${esc(addressText(a))}</span>${a.isDefault?badge('Mặc định','orange'):''}</span></label>`).join('')||'<p class="muted">Bạn cần thêm địa chỉ nhận hàng.</p>'}</div></section><section class="panel"><h3 class="panel-title">02 / Phương thức thanh toán</h3><div class="grid2"><label class="payment-option"><input type="radio" name="method" value="COD" checked><span><strong>Thanh toán khi nhận hàng</strong><small>COD · Thanh toán trực tiếp</small></span></label><label class="payment-option"><input type="radio" name="method" value="VNPAY"><span><strong>VNPay</strong><small>Thanh toán trực tuyến</small></span></label></div></section><section class="panel"><h3 class="panel-title">03 / Kiểm tra sản phẩm</h3>${items.map(i=>`<div class="order-item row" style="margin:12px 0">${image(i.p.customImage||i.p.asset,i.p.name)}<div><strong>${esc(i.p.name)}</strong><p class="small muted">${esc(i.v.ram)} / ${esc(i.v.storage)} · SL ${i.qty}</p></div><strong class="push">${money(i.v.price*i.qty)}</strong></div>`).join('')}${textarea('Ghi chú giao hàng (tùy chọn)','note','','placeholder="Ví dụ: Giao trong giờ hành chính" maxlength="300"')}</section></div><div class="stack">${orderSummary(false)}<button class="btn primary full" type="submit" ${!state.addresses.length?'disabled':''}>Đặt hàng ${icon('arrow-right')}</button><p class="small muted" style="font-size:10px;text-align:center">Đặt hàng trong prototype chỉ cập nhật dữ liệu mẫu trên trình duyệt.</p></div></form>`}</main>${footer()}`;}
function orderSuccess(payment=false){const o=currentOrder();return `${shopHeader()}<main id="main" class="container section"><section class="panel success-panel">${image('workspace-box','Đơn hàng được chuẩn bị cẩn thận')}${badge(payment?'THANH TOÁN THÀNH CÔNG':'ĐẶT HÀNG THÀNH CÔNG','green')}<h1>${payment?'Thanh toán thành công!':'Chiếc laptop mới sắp đến rồi!'}</h1><p>Cảm ơn bạn đã lựa chọn LaptopStore. Đơn hàng của bạn đã được ghi nhận và sẽ sớm được chuẩn bị.</p><strong>Đơn hàng #${o.id}</strong><div class="total-box"><div class="row between"><div><small class="muted">Tổng thanh toán</small><h2 style="color:var(--orange);margin-top:5px">${money(orderTotal(o))}</h2></div><div><small class="muted">Phương thức thanh toán</small><p style="font-weight:600;margin-top:5px">${o.method==='COD'?'Thanh toán khi nhận hàng':'VNPay'}</p></div></div></div><div class="row" style="justify-content:center">${link('Theo dõi đơn hàng','tracking','btn primary')}${link('Tiếp tục mua sắm','catalog','btn')}</div></section></main>${footer()}`;}
function paymentPage(){const o=currentOrder();const failed=route==='payFail';return `${shopHeader()}<main id="main" class="container section">${heading('ĐƠN HÀNG / '+o.id,failed?'Thanh toán chưa hoàn tất':'Hoàn tất thanh toán của bạn',failed?'Đơn hàng vẫn được lưu. Bạn có thể thử lại khi sẵn sàng.':'Kiểm tra đơn hàng trước khi tiếp tục thanh toán.')}<div class="content-columns"><div class="panel"><div class="empty"><div class="empty-icon" style="${failed?'background:#fff0f0;color:var(--red)':''}">${icon(failed?'alert':'wallet')}</div><h2>${failed?'Giao dịch chưa thành công':'Tiếp tục thanh toán qua VNPay'}</h2><p>${failed?'Lần thanh toán trước chưa được ghi nhận thành công. Hãy kiểm tra phương thức thanh toán và thử lại.':'Phiên thanh toán này là mô phỏng để bạn xem được cả trạng thái thành công và thất bại.'}</p><div class="row">${button(failed?'Thanh toán lại':'Tiếp tục với VNPay','gateway','primary')}${link('Chi tiết đơn hàng','tracking','btn')}</div></div></div>${orderSummary(false,o)}</div></main>${footer()}`;}
function accountNav(active){return `<aside class="account-nav"><div class="avatar">MA</div><strong>${esc(state.profile.name)}</strong><small class="muted" style="display:block;margin-top:4px">${esc(state.profile.email)}</small><nav aria-label="Tài khoản">${[['profile','Hồ sơ'],['addresses','Sổ địa chỉ'],['orders','Đơn hàng'],['password','Đổi mật khẩu'],['ai','Tư vấn AI'],['login','Đăng xuất']].map(([r,l])=>link(l,r,r===active?'active':'')).join('')}</nav></aside>`;}
function accountPage(){let content='';if(route==='profile')content=`<form class="panel stack" data-form="profile"><div class="row"><div class="avatar">MA</div><div><h3>${esc(state.profile.name)}</h3><small class="muted">Thành viên LaptopStore</small></div>${badge('Đang hoạt động','green')}</div><hr style="margin:0"><div class="field-row">${field('Họ và tên','name',state.profile.name,'text','required maxlength="80"')}${field('Số điện thoại','phone',state.profile.phone,'tel','required pattern="[0-9+ ()-]{9,15}"')}</div>${field('Email đăng nhập','email',state.profile.email,'email','readonly')}<small class="muted">Email được sử dụng để đăng nhập và nhận thông tin đơn hàng.</small><div class="form-actions">${link('Đổi mật khẩu','password','btn')}<button class="btn primary">Lưu hồ sơ</button></div></form>`;
if(route==='password')content=`<form class="panel stack" data-form="password"><h3>Thiết lập mật khẩu mới</h3>${field('Mật khẩu hiện tại','old','','password','required minlength="6" autocomplete="current-password"')}${field('Mật khẩu mới','password','','password','required minlength="6" autocomplete="new-password"')}${field('Xác nhận mật khẩu mới','confirm','','password','required minlength="6" autocomplete="new-password"')}<div class="notice">${icon('lock')}<div><strong>Một mật khẩu tốt, thêm một lớp an tâm</strong><p>Sử dụng từ 6 ký tự, kết hợp chữ, số và ký tự đặc biệt.</p></div></div><div class="form-actions">${link('Quay lại hồ sơ','profile','btn')}<button class="btn primary">Lưu mật khẩu mới</button></div></form>`;
if(route==='addresses')content=`<div class="stack"><div class="row between"><h3>Địa chỉ giao hàng</h3>${button(icon('plus')+' Thêm địa chỉ','edit-address','primary sm')}</div>${state.addresses.length?state.addresses.map(a=>`<article class="panel"><div class="row between wrap"><strong>${esc(a.name)} · ${esc(a.phone)}</strong>${a.isDefault?badge('Mặc định','orange'):''}</div><p class="muted small" style="margin:12px 0 20px">${esc(addressText(a))}</p><div class="row wrap">${button('Chỉnh sửa','edit-address','sm',`data-id="${a.id}"`)}${!a.isDefault?button('Đặt mặc định','default-address','sm',`data-id="${a.id}"`):''}${button('Xóa địa chỉ','delete-address','sm danger',`data-id="${a.id}"`)}</div></article>`).join(''):empty('Chưa có địa chỉ nhận hàng','Thêm địa chỉ để lần thanh toán tiếp theo nhanh chóng hơn.','Thêm địa chỉ','addressEdit')}</div>`;
if(route==='addressEdit')content=addressForm(ui.editing);
const title=({profile:'Hồ sơ của bạn',addresses:'Sổ địa chỉ',addressEdit:ui.editing?'Chỉnh sửa địa chỉ':'Thêm địa chỉ nhận hàng',password:'Đổi mật khẩu'})[route];return `${shopHeader()}<main id="main" class="container section">${heading('TÀI KHOẢN CỦA TÔI',title,'Thông tin chính xác, trải nghiệm thuận tiện hơn.')}<div class="account-layout">${accountNav(['addressEdit'].includes(route)?'addresses':route)}<div>${content}</div></div></main>${footer()}`;}
function addressForm(id,modalForm=false){const a=state.addresses.find(a=>a.id===id)||{};return `<form class="stack ${modalForm?'':'panel'}" data-form="address" data-id="${esc(id||'')}" data-checkout="${modalForm?'1':''}"><div class="field-row">${field('Họ tên người nhận *','name',a.name||state.profile.name,'text','required maxlength="80"')}${field('Số điện thoại *','phone',a.phone||state.profile.phone,'tel','required pattern="[0-9+ ()-]{9,15}"')}</div>${field('Số nhà, tên đường *','street',a.street||'','text','required maxlength="150"')}<div class="field-row">${field('Tỉnh / Thành phố *','city',a.city||'','text','required')}${field('Quận / Huyện','district',a.district||'')}</div><div class="field-row">${field('Phường / Xã','ward',a.ward||'')}${field('Mã bưu chính','postal',a.postal||'','text','pattern="[0-9]{5,6}"')}</div><label class="check-label"><input type="checkbox" name="isDefault" ${a.isDefault||!state.addresses.length?'checked':''}>Đặt làm địa chỉ mặc định</label><div class="form-actions">${modalForm?button('Hủy','close-modal'):link('Quay lại sổ địa chỉ','addresses','btn')}<button class="btn primary">Lưu địa chỉ</button></div></form>`;}
function orderCards(){const mine=state.orders.filter(o=>o.customerId==='u1');const list=mine.filter(o=>!ui.orderFilter||o.status===ui.orderFilter);return `<div class="chips" style="margin-top:0">${[['','Tất cả'],['PENDING','Chờ xác nhận'],['PROCESSING','Đang chuẩn bị'],['SHIPPING','Đang giao'],['DELIVERED','Đã giao']].map(([v,l])=>`<button class="chip ${ui.orderFilter===v?'active':''}" data-action="order-filter" data-value="${v}">${l}</button>`).join('')}</div><div class="stack">${list.length?list.map(o=>`<article class="panel order-card"><div class="row between wrap order-meta"><strong>#${o.id}</strong><small class="muted">${new Date(o.date).toLocaleDateString('vi-VN')}</small><span class="push">${statusBadge(o.status)}</span></div>${o.items.map(i=>`<div class="order-item">${image(i.asset,i.name)}<div><h3>${esc(i.name)}</h3><p class="small muted">${esc(i.variant)} · SL ${i.qty}</p></div><strong class="push">${money(i.price*i.qty)}</strong></div>`).join('')}<div class="order-actions"><div class="muted small">${o.method==='COD'?'Thanh toán khi nhận hàng':'VNPay'} · ${paymentBadge(o.payment)}</div><div class="row">${o.status==='DELIVERED'?button('Viết đánh giá','review-order','sm',`data-id="${o.id}"`):''}${button('Xem chi tiết','view-order','sm',`data-id="${o.id}"`)}</div></div></article>`).join(''):empty('Chưa có đơn ở trạng thái này','Các đơn hàng phù hợp sẽ xuất hiện tại đây.','Khám phá laptop','catalog')}</div>`;}
function timeline(o){const stages=['PENDING','CONFIRMED','PROCESSING','SHIPPING','DELIVERED'];const current=stages.indexOf(o.status);return `<div class="timeline">${stages.map((s,i)=>`<div class="timeline-step ${i<current?'done':i===current?'current':''}"><div class="step-dot">${i<current?'✓':i+1}</div><strong>${labels[s]}</strong><small>${esc(o.history.find(h=>h.status===s)?.date||'Tiếp theo')}</small></div>`).join('')}</div>`;}
function orderedItems(o){return o.items.map(i=>`<div class="order-item row" style="margin:18px 0">${image(i.asset,i.name)}<div><h3 style="font-size:15px">${esc(i.name)}</h3><p class="small muted">${esc(i.variant)}</p><p class="small muted">SKU ${i.sku} · Số lượng ${i.qty}</p></div><strong class="push">${money(i.price*i.qty)}</strong></div>`).join('');}
function tracking(){const o=currentOrder();return `${shopHeader()}<main id="main" class="container section">${heading('ĐƠN HÀNG CỦA TÔI','Đơn hàng #'+o.id,'Đặt lúc '+new Date(o.date).toLocaleString('vi-VN'),link('Tất cả đơn hàng','orders','btn'))}<div class="content-columns"><div class="stack"><section class="panel"><div class="row between wrap"><h3>Hành trình đơn hàng</h3>${statusBadge(o.status)}</div>${['CANCELLED','RETURNED'].includes(o.status)?`<div class="notice red" style="margin-top:20px">${icon('alert')}Đơn hàng ${labels[o.status].toLowerCase()}.</div>`:timeline(o)}<div class="notice ${o.status==='DELIVERED'?'green':''}">${icon(o.status==='DELIVERED'?'check':'truck')}<p>${({PENDING:'Đơn hàng đang chờ được xác nhận.',CONFIRMED:'Đơn hàng đã được xác nhận. Chúng tôi sẽ chuẩn bị hàng sớm.',PROCESSING:'Chúng tôi đang kiểm tra cấu hình và đóng gói cẩn thận.',SHIPPING:'Chiếc laptop của bạn đang trên đường giao tới.',DELIVERED:'Đơn hàng đã được giao. Cảm ơn bạn đã tin tưởng LaptopStore.',CANCELLED:'Đơn đã hủy. Tồn kho đã được hoàn lại.',RETURNED:'Đơn hàng đã được ghi nhận trả hàng.'})[o.status]}</p></div></section><section class="panel"><h3>Sản phẩm trong đơn</h3>${orderedItems(o)}</section><section class="panel"><h3>Thông tin giao hàng</h3><p style="margin:15px 0 5px;font-weight:600">${esc(o.name)} · ${esc(o.phone)}</p><p class="muted small">${esc(o.address)}</p></section></div><div class="stack">${orderSummary(false,o)}<div class="panel"><h3 style="margin-bottom:15px">Thanh toán</h3>${paymentBadge(o.payment)}<p class="small muted" style="margin-top:12px">Phương thức: ${o.method==='COD'?'Thanh toán khi nhận hàng':'VNPay'}</p>${o.method==='VNPAY'&&o.payment!=='PAID'&&o.status!=='CANCELLED'?link('Tiếp tục thanh toán','payPending','btn primary full') :''}</div>${o.status==='PENDING'&&o.payment!=='PAID'?button('Hủy đơn hàng','cancel-order','danger',`data-id="${o.id}"`):''}${o.status==='DELIVERED'?button('Đánh giá sản phẩm','review-order','primary',`data-id="${o.id}"`):''}</div></div></main>${footer()}`;}
function customerOrders(){return `${shopHeader()}<main id="main" class="container section">${heading('TÀI KHOẢN CỦA TÔI','Đơn hàng của bạn','Theo dõi từng chặng đường của chiếc laptop mới.')}<div class="account-layout">${accountNav('orders')}<div>${orderCards()}</div></div></main>${footer()}`;}
function reviewPage(){const o=currentOrder().status==='DELIVERED'?currentOrder():state.orders.find(o=>o.status==='DELIVERED');const item=o?.items[0];const old=state.reviews.find(r=>r.order===o?.id&&r.sku===item?.sku);if(old)ui.rating=old.rating;return `${shopHeader()}<main id="main" class="container section">${heading('TRẢI NGHIỆM CỦA BẠN','Chia sẻ cảm nhận','Một đánh giá nhỏ, thêm một lựa chọn đúng cho người mua sau.')}${!item?empty('Bạn chưa có sản phẩm đủ điều kiện đánh giá','Bạn có thể viết đánh giá sau khi đơn hàng đã được giao.','Xem đơn hàng','orders'):`<div class="content-columns"><form class="panel stack" data-form="review" data-order="${o.id}" data-sku="${item.sku}"><h3>Bạn thấy chiếc laptop này thế nào?</h3><div><span class="small muted">Mức độ hài lòng của bạn</span><div class="stars-input" role="group" aria-label="Chọn số sao">${[1,2,3,4,5].map(i=>`<button type="button" class="${i<=ui.rating?'on':''}" data-action="rating" data-rating="${i}" aria-label="${i} sao" aria-pressed="${i===ui.rating}">★</button>`).join('')}</div></div>${textarea('Nội dung đánh giá','comment',old?.comment||'','required minlength="10" maxlength="2000" placeholder="Chia sẻ trải nghiệm sử dụng của bạn..."')}<div class="notice">${icon('shield')}Đánh giá được gắn với sản phẩm bạn đã mua. Bạn có thể sửa lại sau khi gửi.</div><div class="form-actions">${link('Quay lại đơn hàng','orders','btn')}<button class="btn primary">${old?'Cập nhật đánh giá':'Gửi đánh giá'}</button></div></form><div class="panel">${image(item.asset,item.name)}<h3>${esc(item.name)}</h3><p class="small muted">${esc(item.variant)}</p><p class="small muted" style="margin-top:12px">Đơn hàng #${o.id}</p>${badge('Đã mua hàng','green')}</div></div>`}</main>${footer()}`;}
function auth(){const reg=route==='register';return `${shopHeader()}<main id="main" class="container section"><div class="auth-layout"><div class="auth-story"><div class="eyebrow">CÔNG NGHỆ CHO ĐIỀU BẠN MUỐN</div><h2>Một chiếc laptop.<br>Ngàn điều có thể.</h2><p>Học điều mới. Tạo điều hay.<br>Bắt đầu hành trình cùng LaptopStore.</p>${image('hero-laptop','Laptop cho những ý tưởng mới')}<p class="small">${icon('shield')} Chính hãng · Tận tâm · An toàn</p></div><div class="auth-form"><h1>${reg?'Tạo tài khoản':'Chào mừng trở lại'}</h1><p>${reg?'Cùng bạn tìm chiếc laptop thật phù hợp.':'Đăng nhập để tiếp tục hành trình của bạn.'}</p><form data-form="${reg?'register':'login'}">${reg?field('Họ và tên','name','','text','required maxlength="80" autocomplete="name"'):''}${field('Địa chỉ email','email','','email','required autocomplete="email" placeholder="ban@example.com"')}${reg?field('Số điện thoại','phone','','tel','required pattern="[0-9+ ()-]{9,15}"'):''}${field('Mật khẩu','password','','password','required minlength="6" autocomplete="'+(reg?'new-password':'current-password')+'"')}${reg?field('Xác nhận mật khẩu','confirm','','password','required minlength="6" autocomplete="new-password"'):''}<button class="btn primary full">${reg?'Đăng ký':'Đăng nhập'}</button></form><p class="small muted" style="text-align:center;margin:22px 0">${reg?'Đã có tài khoản?':'Chưa có tài khoản?'} ${link(reg?'Đăng nhập':'Đăng ký',reg?'login':'register','text-btn')}</p>${link('← Quay về cửa hàng','home','text-btn small')}<p class="login-note">Đây là biểu mẫu demo. Không dùng mật khẩu tài khoản thật.</p></div></div></main>${footer()}`;}
function aiPage(){return `${shopHeader()}<main id="main" class="container section">${heading('TƯ VẤN THEO CÁCH CỦA BẠN','Chiếc máy phù hợp, bắt đầu từ một câu hỏi.','Chia sẻ nhu cầu và ngân sách để tìm lựa chọn dành riêng cho bạn.')}<div class="chat-layout"><aside class="panel chat-suggestions"><div class="ai-symbol" style="margin-bottom:20px">${icon('sparkles')}</div><h3>Bắt đầu từ điều bạn cần</h3><p class="small muted" style="margin:12px 0 22px">Từ học tập đến giải trí, mỗi nhu cầu đều có một cấu hình phù hợp.</p>${['Laptop học tập dưới 20 triệu','Chơi game trong tầm 25 triệu','Máy mỏng nhẹ để đi làm','Tôi cần laptop 32GB RAM'].map(t=>`<button data-action="ai-prompt" data-prompt="${t}">${t} ${icon('arrow-right')}</button>`).join('')}<hr><small class="muted">Bản demo tư vấn dựa trên sản phẩm trong prototype.</small></aside><section class="chat-box"><div class="row between" style="padding:18px 22px;border-bottom:1px solid var(--line)"><div class="row">${icon('sparkles')}<strong>Trợ lý LaptopStore</strong></div>${button('Trò chuyện mới','ai-clear','sm')}</div><div class="chat-messages" id="chat-messages"><div class="chat-message"><strong>Chào bạn! Mình có thể giúp gì?</strong><p>Bạn đang tìm laptop để học tập, làm việc hay chơi game? Chia sẻ thêm ngân sách để mình gợi ý nhé.</p></div>${ui.chat.map(m=>m.role==='user'?`<div class="chat-message user">${esc(m.text)}</div>`:`<div class="chat-message"><p>${esc(m.text)}</p>${m.product?`<div class="recommendation">${image(m.product.asset,m.product.name)}<div><strong>${esc(m.product.name)}</strong><p style="color:var(--orange);font-weight:700;margin:5px 0">${money(m.product.variants[0].price)}</p>${link('Xem chi tiết '+icon('arrow-right'),'detail&product='+m.product.id,'text-btn small')}</div></div>`:''}</div>`).join('')}</div><form class="chat-compose" data-form="chat"><input name="prompt" aria-label="Nội dung tin nhắn" required placeholder="Nhập nhu cầu hoặc câu hỏi của bạn..." maxlength="500"><button class="btn primary" aria-label="Gửi tin nhắn">${icon('arrow-right')}<span>Gửi</span></button></form></section></div></main>${footer()}`;}
const staffNav=[['staffOverview','Tổng quan','grid'],['staff','Đơn hàng','orders'],['inventory','Kho hàng','box'],['purchaseOrders','Nhập hàng','truck'],['staffSuppliers','Nhà cung cấp','users'],['payments','Thanh toán','wallet'],['moderation','Đánh giá','star']];
const adminNav=[['admin','Tổng quan','grid'],['products','Sản phẩm','laptop'],['categories','Danh mục','grid'],['brands','Thương hiệu','tag'],['staff','Đơn hàng','orders'],['inventory','Kho hàng','box'],['purchaseOrders','Nhập hàng','truck'],['users','Khách hàng & nhân sự','users'],['couponList','Khuyến mãi','tag'],['suppliers','Nhà cung cấp','truck'],['payments','Thanh toán','wallet'],['report','Báo cáo','chart']];
const activeParent={staffDetail:'staff',staffConfirmed:'staff',staffProcessing:'staff',staffShipping:'staff',staffDelivered:'staff',stockHistory:'inventory',stockAdjust:'inventory',purchaseEdit:'purchaseOrders',purchaseReceive:'purchaseOrders',purchaseDone:'purchaseOrders',paymentDetail:'payments',codConfirmed:'payments',moderationHidden:'moderation',productEdit:'products',userDetail:'users',couponEdit:'couponList',couponUsage:'couponList',supplierEdit:'suppliers'};
function opsLayout(content){const admin=ui.role==='admin';return `<div class="ops"><aside class="sidebar" id="sidebar">${brand()}<p class="nav-label">${admin?'QUẢN TRỊ HỆ THỐNG':'VẬN HÀNH CỬA HÀNG'}</p><nav aria-label="Điều hướng ${admin?'Admin':'Staff'}">${(admin?adminNav:staffNav).map(([r,l,ic])=>link(icon(ic)+'<span>'+l+'</span>',r,(activeParent[route]||route)===r?'active':'')).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-help">${icon('headset')}<strong style="display:block">Một ngày thật hiệu quả</strong><p>Mọi thao tác, cùng một nơi.</p></div>${link(icon('arrow-right')+' Về cửa hàng','home')}${link(icon('grid')+' Chọn trải nghiệm','start')}</div></aside><div class="mobile-backdrop" data-action="toggle-sidebar"></div><div class="ops-shell"><header class="ops-header"><button class="icon-btn mobile-only" data-action="toggle-sidebar" aria-label="Mở menu">${icon('menu')}</button><span class="muted">${admin?'Không gian quản trị':'Không gian nhân viên'}</span><div class="push"><button class="icon-btn" data-action="screen-map" aria-label="Tìm màn hình">${icon('search')}</button><button class="icon-btn" data-action="notifications" aria-label="Thông báo">${icon('bell')}</button><div class="avatar">${admin?'AK':'MA'}</div><span class="user-name">${admin?'Anh Khang':'Minh Anh'}</span></div></header><main id="main" class="ops-main">${content}</main></div></div>`;}
function opsToolbar(kind,placeholder,extra=''){return `<form class="toolbar" data-form="ops-search" data-kind="${kind}"><label class="search">${icon('search')}<input name="q" value="${esc(ui.opsSearch)}" placeholder="${placeholder}" aria-label="${placeholder}"></label><button class="btn sm" type="submit">Tìm kiếm</button>${ui.opsSearch?button('Xóa lọc','clear-ops','sm'):''}<div class="push row wrap">${extra}</div></form>`;}
const searchRows=(rows,keys)=>rows.filter(r=>!ui.opsSearch||keys.map(k=>r[k]).join(' ').toLowerCase().includes(ui.opsSearch.toLowerCase()));
function orderRows(list){return list.map(o=>[primaryCell('#'+o.id,new Date(o.date).toLocaleDateString('vi-VN')),primaryCell(o.name,o.phone),money(orderTotal(o)),statusBadge(o.status),paymentBadge(o.payment),button('Xem đơn '+icon('arrow-right'),'ops-order','sm',`data-id="${o.id}"`)]);}
function chart(){const values=[28,46,35,62,53,77,64,92,75,85,100,88];return `<div class="chart" role="img" aria-label="Biểu đồ doanh thu minh họa theo ngày trong tháng 10">${values.map((v,i)=>`<div class="chart-col"><div class="chart-bar ${i===10?'highlight':''}" style="height:${v*1.55}px" title="Ngày ${i*2+1}: ${v} triệu đồng"></div><small>${String(i*2+1).padStart(2,'0')}</small></div>`).join('')}</div><div class="row between small muted" style="font-size:10px;margin-top:12px"><span>Đơn vị: triệu đồng</span><span>Tháng 10 / 2026 · Dữ liệu minh họa</span></div>`;}
function opsOverview(){const admin=route==='admin';const pending=state.orders.filter(o=>o.status==='PENDING').length;const low=state.products.flatMap(p=>p.variants).filter(v=>v.quantity<=5).length;const paid=state.orders.filter(o=>o.payment==='PAID').reduce((s,o)=>s+orderTotal(o),0);const total=state.orders.reduce((s,o)=>s+orderTotal(o),0);return `${heading(admin?'TỔNG QUAN / THÁNG 10.2026':'VẬN HÀNH / HÔM NAY',admin?'Chào Khang, một ngày tăng trưởng.':'Chào Minh Anh, bắt đầu ngày mới.','Mọi thông tin quan trọng của cửa hàng, trong tầm mắt.',admin?link(icon('chart')+' Xem báo cáo','report','btn primary'):link('Xử lý đơn hàng '+icon('arrow-right'),'staff','btn primary'))}<div class="metrics">${admin?metric('Doanh thu đã thanh toán',money(paid),'Đồng bộ từ đơn hàng demo')+metric('Tổng đơn hàng',state.orders.length,'Theo dữ liệu hiện tại','orders')+metric('Giá trị đơn trung bình',money(total/state.orders.length),'Tất cả đơn trong prototype','wallet')+metric('Sản phẩm đang bán',state.products.filter(p=>p.active).length,'Catalog của cửa hàng','laptop'):metric('Chờ xác nhận',String(pending).padStart(2,'0'),'Cần được xử lý sớm','orders')+metric('Đang chuẩn bị',state.orders.filter(o=>o.status==='PROCESSING').length,'Kiểm tra và đóng gói','box')+metric('COD chưa thu',state.orders.filter(o=>o.method==='COD'&&o.payment==='PENDING'&&o.status!=='CANCELLED').length,'Kiểm tra trạng thái giao hàng','wallet')+metric('SKU tồn thấp',low,'Ngưỡng cảnh báo ≤ 5','alert')}</div><div class="overview-cols"><section class="panel"><div class="row between"><h3>${admin?'Doanh thu theo thời gian':'Đơn hàng cần quan tâm'}</h3>${admin?badge('Tháng 10','orange'):link('Tất cả đơn hàng','staff','text-btn small')}</div>${admin?chart():`<div class="stack" style="margin-top:20px">${state.orders.slice(0,3).map(o=>`<div class="row between" style="padding:14px 0;border-bottom:1px solid var(--line)"><div><strong class="small">#${o.id}</strong><p class="small muted">${esc(o.name)}</p></div>${statusBadge(o.status)}${button(icon('arrow-right'),'ops-order','sm',`data-id="${o.id}" aria-label="Xử lý đơn ${o.id}"`)}</div>`).join('')}</div>`}</section><section class="panel"><div class="row between"><h3>${admin?'Được khách hàng lựa chọn':'Sẵn sàng cho đơn tiếp theo'}</h3>${icon(admin?'chart':'box')}</div>${admin?state.products.slice(0,3).map((p,i)=>`<div class="best-item">${image(p.customImage||p.asset,p.name)}<div><h4>${esc(p.name)}</h4><p>${[48,32,21][i]} lượt quan tâm · Dữ liệu mẫu</p></div><strong class="small push">${i+1}</strong></div>`).join(''):`<div class="notice" style="margin:22px 0">${icon('alert')}<div><strong>${low} SKU cần bổ sung</strong><p>Chủ động nhập hàng để luôn sẵn sàng phục vụ.</p></div></div>${link('Kiểm tra tồn kho','inventory','btn full')}${link('Tạo phiếu nhập','purchaseEdit','btn primary full')}`}<hr><p class="small muted">${admin?'Dữ liệu chi tiết được cập nhật khi bạn thao tác trong prototype.':'Xác nhận COD sau khi đơn đã giao. Các trạng thái thanh toán được theo dõi riêng.'}</p></section></div><section style="margin-top:26px"><div class="section-head"><h3>Đơn hàng gần đây</h3>${link('Xem tất cả','staff','text-btn small')}</div>${table(['ĐƠN HÀNG','KHÁCH HÀNG','TỔNG TIỀN','TRẠNG THÁI ĐƠN','THANH TOÁN',''],orderRows(state.orders.slice(0,4)))}</section>`;}
function staffOrders(){const list=searchRows(state.orders,['id','name','phone']).filter(o=>!ui.orderFilter||o.status===ui.orderFilter);return `${heading('VẬN HÀNH / ĐƠN HÀNG','Mỗi đơn hàng, một trải nghiệm tốt.','Theo dõi và xử lý đơn hàng của cửa hàng.')}<div class="metrics">${['PENDING','CONFIRMED','SHIPPING','DELIVERED'].map(s=>metric(labels[s],String(state.orders.filter(o=>o.status===s).length).padStart(2,'0'),'Đơn hàng trong trạng thái này','orders')).join('')}</div>${opsToolbar('orders','Tìm mã đơn, tên hoặc điện thoại...',`<select data-ops-filter="orderFilter" aria-label="Lọc trạng thái đơn">${[['','Tất cả trạng thái'],...['PENDING','CONFIRMED','PROCESSING','SHIPPING','DELIVERED','CANCELLED'].map(s=>[s,labels[s]])].map(([v,l])=>option(v,l,ui.orderFilter)).join('')}</select>`)}${table(['MÃ ĐƠN / THỜI GIAN','KHÁCH HÀNG','TỔNG TIỀN','TRẠNG THÁI ĐƠN','THANH TOÁN',''],orderRows(list))}<div class="table-bottom"><span>${list.length} đơn hàng phù hợp</span><span>Thông tin thanh toán được theo dõi riêng với trạng thái đơn.</span></div>`;}
function staffOrderDetail(){const o=currentOrder();const next=({PENDING:'CONFIRMED',CONFIRMED:'PROCESSING',PROCESSING:'SHIPPING',SHIPPING:'DELIVERED'})[o.status];const actionText=({CONFIRMED:'Xác nhận đơn',PROCESSING:'Chuẩn bị hàng',SHIPPING:'Bàn giao vận chuyển',DELIVERED:'Xác nhận đã giao'})[next];return `${heading('ĐƠN HÀNG / #'+o.id,'Chi tiết đơn hàng','Đặt ngày '+new Date(o.date).toLocaleDateString('vi-VN'),link('Quay lại danh sách','staff','btn')+(next?button(actionText,'order-next','primary',`data-id="${o.id}" data-next="${next}"`):''))}<div class="ops-cols"><div class="stack"><section class="panel"><div class="row between wrap"><h3>Sản phẩm trong đơn</h3>${statusBadge(o.status)}</div>${orderedItems(o)}</section><section class="panel"><h3 class="panel-title">Thông tin người nhận</h3><strong>${esc(o.name)} · ${esc(o.phone)}</strong><p class="small muted" style="margin-top:8px">${esc(o.address)}</p></section><section class="panel"><h3>Hành trình đơn hàng</h3>${timeline(o)}${table(['TRẠNG THÁI','THỜI GIAN'],o.history.map(h=>[statusBadge(h.status),esc(h.date)]))}</section></div><div class="stack">${orderSummary(false,o)}<section class="panel"><h3 class="panel-title">Thanh toán ${o.method}</h3>${paymentBadge(o.payment)}<p class="small muted" style="margin:12px 0">COD chỉ được xác nhận thu khi đơn đã giao.</p>${o.method==='COD'&&o.status==='DELIVERED'&&o.payment==='PENDING'?button('Xác nhận thu COD','collect-cod','primary full',`data-id="${o.id}"`):''}${button('Xem thanh toán','view-payment','full',`data-id="${o.id}"`)}</section>${o.status==='PENDING'&&o.payment!=='PAID'?button('Hủy đơn hàng','cancel-order','danger',`data-id="${o.id}"`):''}</div></div>`;}
function inventory(){const all=state.products.flatMap(p=>p.variants.map(v=>({...v,product:p.name,asset:p.asset})));const list=searchRows(all,['sku','product']).filter(v=>!ui.inventoryLow||v.quantity<=5);return `${heading('VẬN HÀNH / KHO HÀNG','Tồn kho luôn trong tầm mắt.','Theo dõi tồn thực tế theo từng cấu hình và SKU.',(ui.role==='admin'?link('Điều chỉnh tồn','stockAdjust','btn'):'')+link(icon('plus')+' Tạo phiếu nhập','purchaseEdit','btn primary'))}<div class="metrics">${metric('Tổng biến thể',all.length,'Đang quản lý','laptop')}${metric('Số lượng tồn',all.reduce((s,v)=>s+v.quantity,0),'Theo từng SKU','box')}${metric('Sắp hết hàng',all.filter(v=>v.quantity>0&&v.quantity<=5).length,'Ngưỡng cảnh báo ≤ 5','alert')}${metric('Hết hàng',all.filter(v=>v.quantity===0).length,'Cần bổ sung sớm','box')}</div>${opsToolbar('inventory','Tìm tên sản phẩm hoặc SKU...',`<label class="check-label"><input type="checkbox" data-ops-filter="inventoryLow" ${ui.inventoryLow?'checked':''}>Chỉ xem tồn thấp</label>`)}${table(['SKU','SẢN PHẨM / CẤU HÌNH','GIÁ BÁN','TỒN KHO','TRẠNG THÁI',''],list.map(v=>[primaryCell(v.sku),primaryCell(v.product,v.ram+' / '+v.storage+' / '+v.color),money(v.price),`<strong style="color:${v.quantity<=5?'var(--orange)':'inherit'}">${v.quantity}</strong>`,badge(v.quantity===0?'Hết hàng':v.quantity<=5?'Sắp hết hàng':'Còn hàng',v.quantity===0?'red':v.quantity<=5?'orange':'green'),button('Lịch sử '+icon('arrow-right'),'sku-history','sm',`data-sku="${v.sku}"`)]))}<div class="table-bottom"><span>${list.length} biến thể</span>${link('Tất cả biến động kho','stockHistory','text-btn')}</div>`;}
function stockHistory(){const list=state.movements.filter(m=>!ui.historySku||m.sku===ui.historySku);return `${heading('KHO HÀNG / LỊCH SỬ','Mọi thay đổi đều được ghi nhận.',ui.historySku?'Đang xem SKU '+esc(ui.historySku):'Lịch sử nhập, xuất và điều chỉnh kho.',button('Xem tất cả','all-history')+link('Về tồn kho','inventory','btn primary'))}${table(['THỜI GIAN','SKU','NGHIỆP VỤ','THAY ĐỔI','TRƯỚC / SAU','THAM CHIẾU / LÝ DO'],list.map(m=>[esc(m.date),primaryCell(m.sku),badge(({SALE:'Xuất bán',PURCHASE_RECEIPT:'Nhập hàng',ADJUSTMENT:'Điều chỉnh',RESTORE:'Hoàn kho'})[m.type]||m.type,m.delta>0?'green':'orange'),`<strong style="color:${m.delta>0?'var(--green)':'var(--orange)'}">${m.delta>0?'+':''}${m.delta}</strong>`,`${m.before} → ${m.after}`,primaryCell(m.reference,m.note)]))}<div class="table-bottom"><span>${list.length} biến động</span><span>Cập nhật tự động sau các thao tác trong prototype.</span></div>`;}
function stockAdjust(){const sku=ui.adjustSku||'ROG-G15-01';const found=findSku(sku)||findSku(state.products[0].variants[0].sku);return `${heading('QUẢN TRỊ / KHO HÀNG','Điều chỉnh tồn kho','Mỗi điều chỉnh cần có lý do và được ghi lại trong lịch sử.',link('Quay lại kho hàng','inventory','btn'))}<div class="ops-cols"><form class="panel stack" data-form="adjust"><h3>Thông tin điều chỉnh</h3>${selectField('Chọn SKU','sku',state.products.flatMap(p=>p.variants.map(v=>[v.sku,p.name+' · '+v.sku])),found.v.sku)}<div class="field-row">${field('Số lượng thay đổi (+ tăng / − giảm)','delta',1,'number','required step="1"')}${field('Tồn hiện tại','before',found.v.quantity,'number','readonly')}</div><div class="notice" id="adjust-preview">${icon('box')}Tồn sau điều chỉnh: <strong>${found.v.quantity+1}</strong></div>${textarea('Lý do điều chỉnh *','reason','','required minlength="5" maxlength="300" placeholder="Ví dụ: Kiểm kê thực tế và đối chiếu tồn kho"')}<div class="form-actions"><button class="btn primary">Xác nhận điều chỉnh</button></div></form><div class="panel"><div class="ai-symbol" style="margin-bottom:18px">${icon('shield')}</div><h3>Rõ ràng ở từng con số</h3><p class="muted small" style="margin-top:12px">Lưu số lượng trước và sau, lý do điều chỉnh, thời điểm và người thực hiện. Tổng tồn không được âm.</p></div></div>`;}
function purchases(){const list=searchRows(state.purchases,['id','status']);return `${heading('VẬN HÀNH / NHẬP HÀNG','Luôn sẵn sàng cho đơn hàng mới.','Tạo phiếu và theo dõi số lượng đã nhận từ nhà cung cấp.',link(icon('plus')+' Tạo phiếu nhập','purchaseEdit','btn primary'))}${opsToolbar('purchases','Tìm mã phiếu nhập...')}${table(['PHIẾU NHẬP','NHÀ CUNG CẤP','SỐ LƯỢNG ĐẶT / NHẬN','GIÁ TRỊ','TRẠNG THÁI',''],list.map(p=>[primaryCell(p.id,p.date),esc(state.suppliers.find(s=>s.id===p.supplier)?.name||'—'),`${p.lines.reduce((s,l)=>s+l.qty,0)} / ${p.lines.reduce((s,l)=>s+l.received,0)}`,money(p.lines.reduce((s,l)=>s+l.qty*l.cost,0)),statusBadge(p.status),button('Chi tiết '+icon('arrow-right'),'view-po','sm',`data-id="${p.id}"`)]))}<div class="table-bottom"><span>${list.length} phiếu nhập</span><span>Hỗ trợ nhận hàng nhiều lần.</span></div>`;}
function purchaseLine(i=0){return `<div class="po-line" data-line="${i}">${selectField('Sản phẩm / SKU','sku'+i,state.products.flatMap(p=>p.variants.map(v=>[v.sku,p.name+' / '+v.sku])),'ROG-G15-01')}${field('Số lượng','qty'+i,10,'number','required min="1" max="10000" step="1"')}${field('Đơn giá nhập (₫)','cost'+i,20000000,'number','required min="1" step="1"')}<button type="button" class="icon-btn" data-action="remove-po-line" aria-label="Xóa dòng nhập">${icon('close')}</button></div>`;}
function purchaseCreate(){return `${heading('NHẬP HÀNG / PHIẾU MỚI','Tạo phiếu nhập hàng','Chuẩn bị đúng cấu hình, đúng số lượng cho cửa hàng.',link('Quay lại danh sách','purchaseOrders','btn'))}<form data-form="purchase" class="stack"><section class="panel stack"><h3>Thông tin phiếu nhập</h3>${selectField('Nhà cung cấp *','supplier',state.suppliers.filter(s=>s.active).map(s=>[s.id,s.name]),'s1')}${textarea('Ghi chú','note','','maxlength="300" placeholder="Ghi chú về lô hàng hoặc thời gian dự kiến nhận"')}</section><section class="panel"><div class="row between panel-title"><h3>Sản phẩm cần nhập</h3>${button(icon('plus')+' Thêm dòng','add-po-line','sm')}</div><div class="po-lines" id="po-lines">${purchaseLine()}</div><div class="form-actions">${link('Hủy tạo phiếu','purchaseOrders','btn')}<button class="btn primary">Lưu phiếu nhập</button></div></section></form>`;}
function purchaseReceive(){const p=state.purchases.find(p=>p.id===ui.purchase)||state.purchases[0];const done=p.status==='RECEIVED'||route==='purchaseDone';return `${heading('NHẬP HÀNG / '+p.id,done?'Đã ghi nhận hàng nhập kho.':'Nhận hàng từ nhà cung cấp',state.suppliers.find(s=>s.id===p.supplier)?.name||'',link('Danh sách phiếu nhập','purchaseOrders','btn'))}${route==='purchaseDone'?`<div class="notice green" style="margin-bottom:24px">${icon('check')}Số lượng thực nhận đã được cộng tồn và ghi vào lịch sử kho.</div>`:''}<div class="ops-cols"><form data-form="receive" data-id="${p.id}" class="panel stack"><div class="row between wrap"><h3>Số lượng nhận lần này</h3>${statusBadge(p.status)}</div>${table(['SKU / SẢN PHẨM','ĐÃ ĐẶT','ĐÃ NHẬN','NHẬN THÊM'],p.lines.map((l,i)=>[primaryCell(l.sku,findSku(l.sku)?.p.name),l.qty,l.received,`<input aria-label="Nhận thêm ${l.sku}" class="table-input" type="number" name="receive${i}" min="0" max="${l.qty-l.received}" step="1" value="${l.qty-l.received}" ${['RECEIVED','CANCELLED'].includes(p.status)?'disabled':''}>`]))}<p class="small muted">Chỉ nhập số lượng mới nhận trong lần này. Không nhập lại số đã nhận trước đó.</p>${!['RECEIVED','CANCELLED'].includes(p.status)?`<div class="form-actions"><button class="btn primary">Xác nhận nhận hàng</button></div>`:link('Xem lịch sử kho','stockHistory','btn primary')}</form><div class="panel stack"><h3>Thông tin phiếu</h3><div class="summary-line"><span class="muted">Ngày tạo</span><strong>${p.date}</strong></div><div class="summary-line"><span class="muted">Tổng giá trị</span><strong>${money(p.lines.reduce((s,l)=>s+l.qty*l.cost,0))}</strong></div><p class="small muted">${esc(p.note||'Không có ghi chú.')}</p>${p.status==='DRAFT'?button('Hủy phiếu nháp','cancel-po','danger',`data-id="${p.id}"`):''}</div></div>`;}
function suppliers(){const readonly=route==='staffSuppliers';const list=searchRows(state.suppliers,['name','email','phone']);return `${heading((readonly?'VẬN HÀNH':'QUẢN TRỊ')+' / NHÀ CUNG CẤP',readonly?'Đối tác đồng hành của cửa hàng.':'Quản lý nhà cung cấp','Thông tin liên hệ và trạng thái hợp tác.',!readonly?button(icon('plus')+' Thêm nhà cung cấp','new-supplier','primary'):'')}${opsToolbar('suppliers','Tìm tên, email hoặc điện thoại...')}${table(['NHÀ CUNG CẤP','LIÊN HỆ','ĐỊA CHỈ','TRẠNG THÁI',''],list.map(s=>[primaryCell(s.name),primaryCell(s.email,s.phone),esc(s.address),badge(s.active?'Đang hợp tác':'Tạm ngưng',s.active?'green':'neutral'),button(readonly?'Xem thông tin':'Chỉnh sửa','edit-supplier','sm',`data-id="${s.id}" data-readonly="${readonly?'1':''}"`)]))}`;}
function supplierEditor(){const s=state.suppliers.find(s=>s.id===ui.editing)||{};return `${heading('NHÀ CUNG CẤP / THÔNG TIN',s.id?'Chỉnh sửa nhà cung cấp':'Thêm nhà cung cấp','Thông tin chính xác giúp công việc phối hợp thuận tiện hơn.',link('Quay lại danh sách','suppliers','btn'))}<form class="panel stack" data-form="supplier" data-id="${s.id||''}">${field('Tên nhà cung cấp *','name',s.name||'','text','required maxlength="120"')}<div class="field-row">${field('Email liên hệ *','email',s.email||'','email','required')}${field('Số điện thoại *','phone',s.phone||'','tel','required pattern="[0-9+ ()-]{9,15}"')}</div>${textarea('Địa chỉ','address',s.address||'','required')}<label class="check-label"><input type="checkbox" name="active" ${s.active!==false?'checked':''}>Đang hợp tác</label><div class="form-actions"><button class="btn primary">Lưu nhà cung cấp</button></div></form>`;}
function payments(){const list=searchRows(state.orders,['id','name']).filter(o=>!ui.filterPayment||o.payment===ui.filterPayment);return `${heading('VẬN HÀNH / THANH TOÁN','Rõ ràng từng giao dịch.','Theo dõi phương thức, trạng thái và lịch sử thanh toán.')}<div class="metrics">${metric('Đã thanh toán',money(state.orders.filter(o=>o.payment==='PAID').reduce((s,o)=>s+orderTotal(o),0)),'Từ các đơn đã ghi nhận','wallet')}${metric('Chưa thanh toán',state.orders.filter(o=>o.payment==='PENDING').length,'Theo dõi riêng trạng thái đơn','clock')}${metric('COD chờ thu',state.orders.filter(o=>o.method==='COD'&&o.status==='DELIVERED'&&o.payment==='PENDING').length,'Đơn đã giao, đủ điều kiện thu','wallet')}${metric('Giao dịch',state.transactions.length,'Lịch sử các lần thực hiện','chart')}</div>${opsToolbar('payments','Tìm mã đơn hoặc khách hàng...',`<select data-ops-filter="filterPayment" aria-label="Lọc thanh toán">${[['','Tất cả trạng thái'],['PENDING','Chưa thanh toán'],['PAID','Đã thanh toán'],['FAILED','Thất bại']].map(([v,l])=>option(v,l,ui.filterPayment)).join('')}</select>`)}${table(['ĐƠN HÀNG','KHÁCH HÀNG','PHƯƠNG THỨC','SỐ TIỀN','THANH TOÁN',''],list.map(o=>[primaryCell(o.id),esc(o.name),badge(o.method,o.method==='COD'?'orange':'blue'),money(orderTotal(o)),paymentBadge(o.payment),button('Xem chi tiết','view-payment','sm',`data-id="${o.id}"`)]))}`;}
function paymentDetail(){const o=currentOrder();const tx=state.transactions.filter(t=>t.order===o.id);return `${heading('THANH TOÁN / #'+o.id,'Chi tiết thanh toán','Trạng thái giao hàng và thanh toán được quản lý độc lập.',link('Quay lại thanh toán','payments','btn'))}${route==='codConfirmed'?`<div class="notice green" style="margin-bottom:24px">${icon('check')}Đã ghi nhận thanh toán COD thành công.</div>`:''}<div class="ops-cols"><div class="stack"><section class="panel stack"><div class="row between"><h3>Thông tin thanh toán</h3>${paymentBadge(o.payment)}</div><div class="grid2"><div><small class="muted">Số tiền</small><h2 style="margin-top:8px;color:var(--orange)">${money(orderTotal(o))}</h2></div><div><small class="muted">Phương thức</small><h3 style="margin-top:8px">${o.method==='COD'?'Thanh toán khi nhận hàng':'VNPay'}</h3></div></div><hr style="margin:0"><div class="row between wrap"><span>Đơn #${o.id}</span>${statusBadge(o.status)}</div>${button('Xem chi tiết đơn hàng','ops-order','',`data-id="${o.id}"`)}</section><section class="panel"><h3 class="panel-title">Lịch sử giao dịch</h3>${table(['MÃ GIAO DỊCH','PHƯƠNG THỨC','SỐ TIỀN','KẾT QUẢ'],tx.map(t=>[primaryCell(t.id,t.date),t.provider,money(t.amount),badge(t.status==='SUCCESS'?'Thành công':'Thất bại',t.status==='SUCCESS'?'green':'red')]))}</section></div><section class="panel stack"><h3>${o.method==='COD'?'Xác nhận thu COD':'Giao dịch VNPay'}</h3><p class="small muted">${o.method==='COD'?'Chỉ xác nhận khi đã thu đủ tiền và đơn hàng đã được giao.':'Giao dịch trực tuyến được cập nhật qua kết quả thanh toán, nhân viên không thay đổi thủ công.'}</p>${o.method==='COD'?button(o.payment==='PAID'?'Đã xác nhận thu COD':'Xác nhận đã thu COD','collect-cod','primary full',`data-id="${o.id}" ${o.status!=='DELIVERED'||o.payment!=='PENDING'?'disabled':''}`):''}${o.method==='COD'&&o.status!=='DELIVERED'?`<p class="small" style="color:var(--orange)">Đơn chưa giao thành công, chưa đủ điều kiện xác nhận thu.</p>`:''}</section></div>`;}
function moderation(){const list=state.reviews.filter(r=>ui.reviewFilter==='all'||(ui.reviewFilter==='visible'?r.visible:!r.visible));return `${heading('VẬN HÀNH / ĐÁNH GIÁ','Giữ trải nghiệm mua sắm đáng tin cậy.','Xem nội dung và ẩn đánh giá vi phạm. Nội dung của khách được giữ nguyên.')}<div class="toolbar"><span class="results-count">${list.length} đánh giá</span><select data-ops-filter="reviewFilter" aria-label="Lọc đánh giá">${[['all','Tất cả đánh giá'],['visible','Đang hiển thị'],['hidden','Đã ẩn']].map(([v,l])=>option(v,l,ui.reviewFilter)).join('')}</select></div>${table(['KHÁCH HÀNG / SẢN PHẨM','ĐIỂM','NỘI DUNG','HIỂN THỊ',''],list.map(r=>[primaryCell(r.name,findSku(r.sku)?.p.name),`<span style="color:#b86710">${'★'.repeat(r.rating)}</span>`,`<div style="white-space:normal;min-width:220px;max-width:400px;line-height:1.8">${esc(r.comment)}</div>`,badge(r.visible?'Đang hiển thị':'Đã ẩn',r.visible?'green':'neutral'),button(r.visible?'Ẩn đánh giá':'Hiển thị lại','toggle-review','sm',`data-id="${r.id}"`)]))}`;}
function adminProducts(){const list=searchRows(state.products,['name','brand','category']);return `${heading('DỮ LIỆU / SẢN PHẨM','Danh mục laptop của cửa hàng.','Quản lý thông tin, cấu hình và trạng thái kinh doanh.',button(icon('plus')+' Thêm sản phẩm','new-product','primary'))}${opsToolbar('products','Tìm tên laptop, thương hiệu...')}${table(['SẢN PHẨM','THƯƠNG HIỆU','DANH MỤC','GIÁ TỪ','BIẾN THỂ','TRẠNG THÁI',''],list.map(p=>[primaryCell(p.name,p.variants[0]?.sku),esc(p.brand),esc(p.category),money(p.variants[0]?.price),p.variants.length,badge(p.active?'Đang bán':'Tạm ẩn',p.active?'green':'neutral'),button('Chỉnh sửa','edit-product','sm',`data-id="${p.id}"`)]))}<div class="table-bottom"><span>${list.length} sản phẩm</span><span>Tồn kho được quản lý tại Kho hàng.</span></div>`;}
function variantEditor(v,i){return `<div class="variant-editor" data-variant="${i}"><div class="field-row">${field('SKU *','sku'+i,v.sku||'','text',`required ${v.sku?'readonly':''}`)}${field('Giá bán (₫) *','price'+i,v.price||'','number','required min="1" step="1"')}</div><div class="field-row" style="margin-top:14px">${field('RAM *','ram'+i,v.ram||'16GB','text','required')}${field('Lưu trữ *','storage'+i,v.storage||'512GB SSD','text','required')}</div><div class="field-row" style="margin-top:14px">${field('Màu sắc *','color'+i,v.color||'Đen','text','required')}${field('Tồn kho (chỉ đọc)','quantity'+i,v.quantity||0,'number','readonly')}</div></div>`;}
function productEditor(){const p=state.products.find(p=>p.id===ui.editing)||{name:'',brand:'ASUS',category:'Gaming',asset:'product-dark',active:true,variants:[{}]};return `${heading('SẢN PHẨM / THÔNG TIN',p.id?'Chỉnh sửa sản phẩm':'Thêm sản phẩm mới','Thông tin nhất quán cho từng cấu hình của cửa hàng.',link('Quay lại sản phẩm','products','btn'))}<form data-form="product" data-id="${p.id||''}" class="split-form"><div class="stack"><section class="panel stack"><h3>Thông tin chung</h3>${field('Tên sản phẩm *','name',p.name,'text','required maxlength="120"')}<div class="field-row">${selectField('Thương hiệu','brand',state.brands.map(b=>b.name),p.brand)}${selectField('Danh mục','category',state.categories.map(c=>c.name),p.category)}</div>${textarea('Mô tả sản phẩm','description',p.description||'','required maxlength="1500"')}</section><section class="panel"><div class="row between panel-title"><h3>Biến thể & giá bán</h3>${button(icon('plus')+' Thêm biến thể','add-variant','sm')}</div><div id="variants">${p.variants.map(variantEditor).join('')}</div><p class="small muted">Biến thể mới bắt đầu với tồn kho 0. Nhập hàng hoặc điều chỉnh tại Kho hàng.</p></section><section class="panel stack"><h3>Thông số kỹ thuật</h3><div class="field-row">${field('CPU','cpu',p.cpu||'')}${field('GPU','gpu',p.gpu||'')}</div>${field('Màn hình','screen',p.screen||'')}<div class="field-row">${field('Pin','battery',p.battery||'')}${field('Trọng lượng','weight',p.weight||'')}</div>${field('Hệ điều hành','os',p.os||'Windows 11')}</section></div><div class="stack"><section class="panel stack"><h3>Hình ảnh sản phẩm</h3><div class="media-upload" id="media-preview">${p.customImage?`<img src="${p.customImage}" alt="Ảnh sản phẩm đã chọn">`:image(p.customImage||p.asset,p.name||'Sản phẩm mới')}<label class="field"><span>Chọn ảnh từ máy</span><input name="photo" type="file" accept="image/png,image/jpeg,image/webp"></label></div>${selectField('Minh họa có sẵn','asset',[['product-dark','Laptop màu đen'],['product-silver','Laptop màu bạc']],p.asset)}<small class="muted">Ảnh được lưu cục bộ trong prototype.</small></section><section class="panel stack"><h3>Trạng thái kinh doanh</h3><label class="check-label"><input type="checkbox" name="active" ${p.active?'checked':''}>Hiển thị trong cửa hàng</label><button class="btn primary full">Lưu sản phẩm</button></section></div></form>`;}
function directories(){const kind=route==='brands'?'brands':'categories',title=kind==='brands'?'Thương hiệu':'Danh mục';const list=state[kind];const edit=list.find(x=>x.id===ui.directoryId)||{};return `${heading('DỮ LIỆU / '+title.toUpperCase(),title+' sản phẩm','Tổ chức catalog rõ ràng, giúp khách tìm đúng lựa chọn.')}<div class="ops-cols"><div>${table([title.toUpperCase(),'SẢN PHẨM','TRẠNG THÁI',''],list.map(x=>[primaryCell(x.name,x.description),state.products.filter(p=>p[kind==='brands'?'brand':'category']===x.name).length,badge(x.active?'Hoạt động':'Tạm ẩn',x.active?'green':'neutral'),button('Chỉnh sửa','edit-directory','sm',`data-id="${x.id}"`)]))}</div><form class="panel stack" data-form="directory" data-kind="${kind}" data-id="${edit.id||''}"><div class="row between"><h3>${edit.id?'Chỉnh sửa':'Thêm '+title.toLowerCase()}</h3>${edit.id?button('Tạo mới','new-directory','sm'):''}</div>${field('Tên '+title.toLowerCase()+' *','name',edit.name||'','text','required maxlength="80"')}${textarea('Mô tả','description',edit.description||'','maxlength="300"')}<label class="check-label"><input type="checkbox" name="active" ${edit.active!==false?'checked':''}>Đang hoạt động</label><button class="btn primary">Lưu ${title.toLowerCase()}</button></form></div>`;}
function userList(){const list=searchRows(state.users,['name','email','phone']).filter(u=>!ui.userRole||u.roles.includes(ui.userRole));return `${heading('HỆ THỐNG / TÀI KHOẢN','Khách hàng & nhân sự','Quản lý thông tin tài khoản, trạng thái và vai trò.')}<div class="metrics">${metric('Khách hàng',state.users.filter(u=>u.roles.includes('USER')).length,'Tài khoản mua sắm','users')}${metric('Nhân viên',state.users.filter(u=>u.roles.includes('STAFF')).length,'Tài khoản vận hành','user')}${metric('Quản trị viên',state.users.filter(u=>u.roles.includes('ADMIN')).length,'Có quyền quản trị','shield')}${metric('Tài khoản khóa',state.users.filter(u=>!u.active).length,'Đang hạn chế truy cập','lock')}</div>${opsToolbar('users','Tìm họ tên, email hoặc điện thoại...',`<select data-ops-filter="userRole" aria-label="Lọc vai trò">${[['','Tất cả vai trò'],['USER','Khách hàng'],['STAFF','Nhân viên'],['ADMIN','Quản trị viên']].map(([v,l])=>option(v,l,ui.userRole||'')).join('')}</select>`)}${table(['HỌ TÊN','EMAIL / ĐIỆN THOẠI','VAI TRÒ','TRẠNG THÁI',''],list.map(u=>[primaryCell(u.name),primaryCell(u.email,u.phone),u.roles.map(r=>badge(r,r==='ADMIN'?'orange':'neutral')).join(' '),badge(u.active?'Hoạt động':'Đã khóa',u.active?'green':'red'),button('Chi tiết','edit-user','sm',`data-id="${u.id}"`)]))}`;}
function userEditor(){const u=state.users.find(u=>u.id===ui.editing)||state.users[1];return `${heading('TÀI KHOẢN / '+esc(u.name),'Thông tin & phân quyền','Một tài khoản có thể được gán nhiều vai trò.',link('Quay lại danh sách','users','btn'))}<div class="ops-cols"><form class="panel stack" data-form="user" data-id="${u.id}"><div class="row"><div class="avatar">${esc(u.name.split(' ').slice(-2).map(s=>s[0]).join(''))}</div><div><h3>${esc(u.name)}</h3><p class="small muted">${esc(u.email)}</p></div></div><div class="field-row">${field('Họ tên','name',u.name,'text','readonly')}${field('Số điện thoại','phone',u.phone,'tel','readonly')}</div><hr style="margin:0"><h3>Vai trò tài khoản</h3><div class="check-grid">${[['USER','Khách hàng'],['STAFF','Nhân viên'],['ADMIN','Quản trị viên']].map(([r,l])=>`<label class="check-pill"><input type="checkbox" name="roles" value="${r}" ${u.roles.includes(r)?'checked':''}><span>${l}<small class="muted" style="display:block">${r}</small></span></label>`).join('')}</div><label class="check-label"><input type="checkbox" name="active" ${u.active?'checked':''}>Tài khoản đang hoạt động</label><div class="form-actions"><button class="btn primary">Lưu vai trò & trạng thái</button></div></form><div class="panel stack"><h3>Phân quyền đúng trách nhiệm</h3><p class="small muted">Khách hàng mua sắm và quản lý thông tin riêng.</p><p class="small muted">Staff xử lý đơn hàng, thanh toán COD, nhập hàng và đánh giá.</p><p class="small muted">Admin quản lý catalog, khuyến mãi, tài khoản và điều chỉnh kho.</p></div></div>`;}
function couponList(){const list=searchRows(state.coupons,['code']);return `${heading('KINH DOANH / KHUYẾN MÃI','Thêm ưu đãi. Thêm lý do lựa chọn.','Quản lý điều kiện, thời gian và lượt sử dụng mã.',button(icon('plus')+' Tạo mã giảm giá','new-coupon','primary'))}${opsToolbar('coupons','Tìm mã giảm giá...')}${table(['MÃ GIẢM GIÁ','ƯU ĐÃI','ĐƠN TỐI THIỂU','LƯỢT DÙNG / GIỚI HẠN','TRẠNG THÁI',''],list.map(c=>[primaryCell(c.code,c.end?'Đến '+c.end:'Không giới hạn'),c.type==='FIXED'?money(c.value):c.value+'%',money(c.min),`${state.orders.filter(o=>o.coupon===c.code&&o.status!=='CANCELLED').length} / ${c.limit}`,badge(c.active?'Hoạt động':'Tạm ngưng',c.active?'green':'neutral'),button('Chỉnh sửa','edit-coupon','sm',`data-id="${c.id}"`)]))}`;}
function couponEditor(){const c=state.coupons.find(c=>c.id===ui.editing)||{code:'',type:'FIXED',value:500000,min:20000000,max:500000,limit:100,perUser:3,start:'2026-10-24',end:'2026-12-31',active:true};return `${heading('KHUYẾN MÃI / ĐIỀU KIỆN',c.id?'Chỉnh sửa mã giảm giá':'Tạo mã giảm giá','Thiết lập ưu đãi phù hợp, kiểm soát rõ giới hạn sử dụng.',link('Quay lại khuyến mãi','couponList','btn'))}<div class="ops-cols"><form class="panel stack" data-form="coupon-edit" data-id="${c.id||''}">${field('Mã giảm giá *','code',c.code,'text','required pattern="[A-Za-z0-9_-]{3,30}" placeholder="Ví dụ: LAPTOP500"')}<div class="field-row">${selectField('Loại giảm giá','type',[['FIXED','Giảm số tiền (₫)'],['PERCENT','Giảm phần trăm (%)']],c.type)}${field('Giá trị giảm *','value',c.value,'number','required min="1"')}</div><div class="field-row">${field('Đơn hàng tối thiểu (₫)','min',c.min,'number','required min="0"')}${field('Mức giảm tối đa (₫)','max',c.max,'number','required min="0"')}</div><div class="field-row">${field('Tổng lượt sử dụng','limit',c.limit,'number','required min="1" step="1"')}${field('Lượt dùng mỗi khách','perUser',c.perUser,'number','required min="1" step="1"')}</div><div class="field-row">${field('Ngày bắt đầu','start',c.start,'date','required')}${field('Ngày kết thúc','end',c.end,'date','required')}</div><label class="check-label"><input type="checkbox" name="active" ${c.active?'checked':''}>Đang hoạt động</label><div class="form-actions"><button class="btn primary">Lưu mã giảm giá</button></div></form><section class="panel stack"><h3>Đúng ưu đãi, đúng thời điểm</h3><p class="small muted">Mã được kiểm tra lại khi khách đặt hàng. Đơn bị hủy sẽ giải phóng lượt dùng.</p>${c.id?button('Lịch sử sử dụng','coupon-usage','',`data-id="${c.id}"`):''}</section></div>`;}
function couponUsage(){const c=state.coupons.find(c=>c.id===ui.editing)||state.coupons[0];const list=state.orders.filter(o=>o.coupon===c.code);return `${heading('KHUYẾN MÃI / '+c.code,'Lịch sử sử dụng mã','Theo dõi đơn hàng và số tiền giảm được ghi nhận.',link('Quay lại khuyến mãi','couponList','btn'))}<div class="metrics">${metric('Lượt đang dùng',list.filter(o=>o.status!=='CANCELLED').length,'Không tính đơn đã hủy','tag')}${metric('Tổng tiền giảm',money(list.filter(o=>o.status!=='CANCELLED').reduce((s,o)=>s+(o.discount||0),0)),'Theo các đơn hợp lệ','wallet')}${metric('Giới hạn lượt',c.limit,'Toàn bộ chiến dịch','users')}${metric('Mỗi khách',c.perUser,'Lượt tối đa','user')}</div>${table(['ĐƠN HÀNG','KHÁCH HÀNG','GIẢM GIÁ','TRẠNG THÁI LƯỢT DÙNG'],list.map(o=>[primaryCell(o.id),esc(o.name),money(o.discount),badge(o.status==='CANCELLED'?'Đã giải phóng':'Đang sử dụng',o.status==='CANCELLED'?'neutral':'green')]))}`;}
function report(){const filtered=state.orders.filter(o=>(!ui.reportFrom||o.date.slice(0,10)>=ui.reportFrom)&&(!ui.reportTo||o.date.slice(0,10)<=ui.reportTo));return `${heading('PHÂN TÍCH / KINH DOANH','Nhìn rõ hôm nay. Sẵn sàng ngày mai.','Tổng hợp dữ liệu đơn hàng và thanh toán của cửa hàng.',button(icon('arrow-right')+' Xuất CSV','export-report','primary'))}<form class="toolbar" data-form="report-filter">${field('Từ ngày','from',ui.reportFrom||'2026-10-01','date')}${field('Đến ngày','to',ui.reportTo||'2026-10-31','date')}<button class="btn" style="align-self:end">Áp dụng</button></form><div class="metrics">${metric('Doanh thu đã thu',money(filtered.filter(o=>o.payment==='PAID').reduce((s,o)=>s+orderTotal(o),0)),'Theo đơn đã thanh toán','wallet')}${metric('Đơn hàng',filtered.length,'Trong khoảng thời gian đã chọn','orders')}${metric('Sản phẩm đã đặt',filtered.reduce((s,o)=>s+o.items.reduce((a,i)=>a+i.qty,0),0),'Tổng số lượng hàng hóa','box')}${metric('Đơn đã hủy',filtered.filter(o=>o.status==='CANCELLED').length,'Theo trạng thái thực tế','alert')}</div><section class="panel" style="margin-bottom:24px"><h3>Xu hướng doanh thu</h3>${chart()}</section>${table(['MÃ ĐƠN','KHÁCH HÀNG','GIÁ TRỊ','TRẠNG THÁI ĐƠN','THANH TOÁN'],filtered.map(o=>[primaryCell(o.id,new Date(o.date).toLocaleDateString('vi-VN')),esc(o.name),money(orderTotal(o)),statusBadge(o.status),paymentBadge(o.payment)]))}`;}
